import type { PracticeExam } from './lccaExams';

// LCPAA practice exams 4-5. Content is based on Texas Chapter 749 (Minimum Standards for Child-Placing Agencies), revised 8/2026.
export const lcpaaExamsPartB: PracticeExam[] = [
  {
    id: 'lcpaa-exam-4',
    number: 4,
    title: 'LCPAA Practice Exam 4 — Rights, Care & Safety',
    description: 'Child rights, daily care and discipline, medical and dental requirements, emergency behavior intervention, and foster home health and safety under Chapter 749 (Subchapters L–O and H).',
    questions: [
      { id: 'p4q1', domain: 'Health & Safety (Subch. H)', question: 'Which feature of a foster home triggers the requirement for at least one carbon monoxide detector?', options: ['A swimming pool or hot tub', 'An attached garage', 'A basement or crawl space', 'A second story with bedrooms'], correct: 1, explanation: 'Under §749.1007(b), a foster home with a gas appliance, propane space heater, fireplace, wood stove, or attached garage must have at least one carbon monoxide detector. Smoke detectors are required separately: in the kitchen, in hallways or open areas outside sleeping spaces, and on each level of a multi-level home (§749.1007(a)).' },
      { id: 'p4q2', domain: 'Health & Safety (Subch. H)', question: 'A new child is placed in a foster home. When must the home practice its disaster and emergency plan with the child?', options: ['Within 72 hours of placement', 'Within the first 14 days of placement', 'Within 90 days of placement', 'Within the first month of placement'], correct: 3, explanation: '§749.1009(c) requires a home to practice the emergency plan with children in care within the first month of placement. Under §749.1009(b), the CPA that verified the home must also review and evaluate the plan every year with all caregivers and children in care, in a way each person understands.' },
      { id: 'p4q3', domain: 'Health & Safety (Subch. H)', question: 'What is the minimum height of the barrier that must surround a foster home swimming pool on all sides?', options: ['Three feet', 'Five feet', 'Four feet', 'Six feet'], correct: 2, explanation: '§749.1061(a) requires a barrier on all sides of a swimming pool that is at least four feet high; an exterior wall of the home may serve as one side. Gates or other access points to a pool or hot tub must be secured with a safety device, such as a bolt lock, and locked when the pool or hot tub is not in use (§749.1061(b)).' },
      { id: 'p4q4', domain: 'Health & Safety (Subch. H)', question: 'A door leads from a foster home directly to a backyard pool area. What does §749.1061(d) require of that door?', options: ['A door alarm, or a lock that only an adult can reach and operate', 'Only a posted warning sign, because the pool barrier already protects children', 'A deadbolt keyed on both sides so that anyone in the home can open it', 'A motion-sensor light that turns on when the door is opened at night'], correct: 0, explanation: '§749.1061(d) says any door leading from the home to an area with a swimming pool, hot tub, or body of water must have a door alarm or a lock that is accessible and operational only by an adult. The lock option has an exception when a state or local fire authority determines the lock violates the fire code; the CPA must then keep that determination in the foster home record.' },
      { id: 'p4q5', domain: 'Health & Safety (Subch. H)', question: 'Five foster children over the age of two are swimming in the home pool. What is the minimum number of caregivers who must supervise the activity area under §749.1065?', options: ['One caregiver, as long as a lifesaving device is on the deck', 'Two caregivers', 'Three caregivers', 'One caregiver for every two children'], correct: 1, explanation: '§749.1065(b) requires at least two caregivers to supervise the activity area when four or more children over the age of two are swimming. Separately, one caregiver must supervise each child under two (§749.1065(a)), and one caregiver must supervise each child who is non-ambulatory or subject to seizures unless a licensed physician documents that special precautions are not needed (§749.1065(c)).' },
      { id: 'p4q6', domain: 'Health & Safety (Subch. H)', question: 'A child in care who cannot swim joins a swimming activity. What must the child wear?', options: ['Inflatable arm bands, provided an adult stays within arm reach of the child', 'A Type IV throwable cushion that the child keeps hold of at all times', 'A fitted, fastened U.S. Coast Guard-approved Type I, II, or III PFD', 'Any pool flotation toy that suits the size and weight of the child'], correct: 2, explanation: '§749.1063(d) requires a child who is unable to swim to wear a personal flotation device that is U.S. Coast Guard-approved with a rating of Type I, II, or III (or a buoyancy level of 70 or above) and is properly fitted and fastened. Caregivers must also assess a child\'s swimming skills before allowing the child in the water, and the CPA must document how the skills were checked in the child\'s record (§749.1063(e)).' },
      { id: 'p4q7', domain: 'Health & Safety (Subch. H)', question: 'After a child in care turns 18, with whom may the child share a sleeping space under §749.1051(c)?', options: ['Another youth who is 16 or older, if the age gap is no more than two years', 'Any adult household member of the same sex who has passed a background check', 'Any other child in care of the same sex, regardless of the difference in age', 'Another youth who is 14 or older, if CPMS approves the arrangement in writing'], correct: 0, explanation: '§749.1051(c)(2) allows a child in care who has had an 18th birthday to share a sleeping space with another youth who is 16 or older, provided the age difference does not exceed two years. Before approving any sharing, the CPMS must document in the service plan that there is no known risk of harm after assessing the relationship, ages, behaviors, and any history of sexual trauma or sexually inappropriate behavior. Up to four children may share a sleeping space with CPMS approval, and an infant may never share a sleeping surface (§749.1051(a), (d)).' },
      { id: 'p4q8', domain: 'Health & Safety (Subch. H)', question: 'A foster parent wants to transport a child in care in a vehicle that contains a handgun. Which condition does §749.1037(b) set?', options: ['It is unloaded, locked in the trunk, and kept out of the child\'s reach during the trip', 'It is unloaded, inaccessible to the child, and secured with a trigger lock at all times', 'The CPA gives written approval for each trip, and the handgun is kept in a locked case', 'It is in the caregiver\'s possession and control, and the caregiver may lawfully carry it'], correct: 3, explanation: '§749.1037(b) allows a caregiver to transport a child in a vehicle where a handgun is present if the handgun is in the possession and control of the caregiver and the caregiver is not prohibited by law from carrying a handgun. Other firearms, weapons, explosive materials, or projectiles may be in the vehicle only if all firearms are unloaded, the items are inaccessible to the child, and possession is legal (§749.1037(a)).' },
      { id: 'p4q9', domain: 'Health & Safety (Subch. H)', question: 'Which of the following may a CPA require of a foster home regarding firearms?', options: ['A discussion at the annual evaluation of whether weapons are present and how they are stored', 'A disclosure to the CPA of the specific types of firearms kept in the home during screening', 'Prompt notice to the CPA every time the types of firearms in the home change over time', 'A written inventory listing the make and model of each firearm kept in the home'], correct: 0, explanation: '§749.1035(c) requires the annual evaluation of the home to include a discussion of whether the home has weapons, firearms, explosive materials, or projectiles and, if so, how they are stored. §749.1035(d)-(e) and §749.1033(b) prohibit a CPA from requiring a home to disclose specific types of firearms or to report changes in the types of firearms. The CPA policy must require locked storage when such items are not in use (§749.1031(a)).' },
      { id: 'p4q10', domain: 'Child Rights (Subch. L)', question: 'Within how many days after the CPA admits a child must the child\'s record contain a signed statement that each required individual reviewed and understood the child\'s rights?', options: ['Within 24 hours', 'Within seven days', 'Within 72 hours', 'Within 30 days'], correct: 1, explanation: '§749.1307(1) requires a statement signed within seven days after the CPA admits a child into care. A signed copy of the "CPS Rights of Children and Youth in Foster Care" meets the requirement. Under §749.1301(c)-(d), the CPA must review the rights with the child and parent, give them a written copy, and present the rights in plain language that is easy to understand.' },
      { id: 'p4q11', domain: 'Child Rights (Subch. L)', question: 'At what age does a child in care have the right to review and sign his or her service plan?', options: ['Age 14 or older', 'Age 12 or older', 'Age 16 or older', 'Age 18 or older'], correct: 0, explanation: '§749.1303(5)(B) gives every child in care the right to actively participate in developing the service plan within the limits of the child\'s comprehension and to receive a copy or summary, and a child 14 years old or older has the right to review and sign the service plan.' },
      { id: 'p4q12', domain: 'Child Rights (Subch. L)', question: 'A caregiver has reasonable suspicion that a child in care was involved in a theft and must search the child in a way that involves removing clothing (beyond outer items such as coats, hats, shoes, and socks). What does §749.1305(b) require?', options: ['Any employee may search if one adult witness of either sex is present in the room', 'A same-sex caregiver may search alone, to protect the privacy of the child being searched', 'The CPA administrator must do the search, with the foster parent as the only witness', 'Only a same-sex caregiver may search, with a same-sex adult witness, and no other children may see'], correct: 3, explanation: '§749.1305(b) requires that only a caregiver of the same sex as the child conduct the search, that an adult witness of the same sex be present, and that other children not witness it. A search is allowed only with reasonable suspicion of a prohibited item that endangers safety, suicidal or self-harm threats, or theft (§749.1305(a)). When a search results in removal of personal items or clothing, §749.1307(3) requires documentation of who searched and witnessed, why, what was searched, and the results.' },
      { id: 'p4q13', domain: 'Child Rights (Subch. L)', question: 'Under §749.1305(c), which body cavity may a caregiver or employee search?', options: ['Only the mouth and ears', 'Only the nostrils and mouth, with a witness present', 'Only the mouth', 'None; every body cavity search is prohibited'], correct: 2, explanation: '§749.1305(c) prohibits a caregiver or employee from conducting a body cavity search of a child in care, with the exception of the mouth of the child. Even a permitted search requires reasonable suspicion under §749.1305(a).' },
      { id: 'p4q14', domain: 'Child Rights (Subch. L)', question: 'A foster parent warns a child in care that, as punishment for breaking a house rule, the child will lose the placement if it happens again. How does §749.1303(4)(A) treat this?', options: ['Allowed, if the foster parent first records the warning in the child\'s service plan', 'Prohibited; a child must not be threatened with loss of placement or shelter as punishment', 'Allowed for children 14 and older, if the house rule was explained at admission', 'Allowed, if the CPA administrator approves the warning in advance of the discipline'], correct: 1, explanation: '§749.1303(4)(A)(vii) says a child in care must not be threatened with the loss of placement or shelter as punishment. The same rule bars shaking, corporal punishment or threats of it, excessive time outside in heat or cold, demeaning make-work, denying food, sleep, a bathroom, mail, or family visits, belittling remarks, demeaning behavior, and EBI used as punishment, aversive conditioning, rebirthing, or hug or holding therapy.' },
      { id: 'p4q15', domain: 'Child Rights (Subch. L)', question: 'A CPA wants to use a photograph of a child in care in a fund-raising brochure. What does §749.1303(3)(M) require?', options: ['Verbal consent from the foster parent, which cannot be withdrawn once the brochure is printed', 'Written consent from the CPA administrator only', 'No consent, as long as the child is not named in the brochure', 'The written consent of the child beforehand, which the child may later withdraw'], correct: 3, explanation: '§749.1303(3)(M) gives a child in care the right to consent in writing before taking part in any publicity or fund-raising activity for the home or the CPA, including use of the child\'s photograph, and to withdraw that consent. Under §749.1303(3)(N), the child also has the right to refuse to make public statements showing gratitude to the home or CPA.' },
      { id: 'p4q16', domain: 'Child Rights (Subch. L)', question: 'Which of the following is an entity that a child in care has the right to contact under §749.1303(7)(B)?', options: ['Disability Rights Texas', 'The Texas Workforce Commission', 'The Texas Education Agency complaints unit', 'The Office of the Attorney General consumer protection division'], correct: 0, explanation: '§749.1303(7)(B) lists the DFPS Abuse/Neglect Hotline, the HHSC Ombudsman for Children and Youth in Foster Care, the DFPS Office of Consumer Affairs, and Disability Rights Texas. Under §749.1303(7)(A), a child may make anonymous calls, reports, or complaints without interference, coercion, punishment, retaliation, or threats of either.' },
      { id: 'p4q17', domain: 'Daily Care & Discipline (Subch. M)', question: 'A crib used for an infant younger than what age must be bare except for a mattress with a tight-fitting sheet?', options: ['6 months', '12 months', '9 months', '18 months'], correct: 1, explanation: '§749.1403(a)(3) requires a crib to be bare, except for a mattress with a tight-fitting sheet, for an infant younger than 12 months. A home may not use a stackable crib, bean bag, waterbed, or foam pad as sleeping equipment for an infant (§749.1403(c)), and the CPA must notify the parent of each child in care of certain crib deficiencies (§749.1403(f)).' },
      { id: 'p4q18', domain: 'Daily Care & Discipline (Subch. M)', question: 'A foster parent wants to swaddle a 5-month-old who has recently learned to roll over without help. What does §749.1405(e) say?', options: ['Swaddling is allowed if a lightweight muslin blanket is used', 'Swaddling is allowed during naps if the infant is placed face-up', 'An infant who can roll over without assistance must not be swaddled', 'Swaddling is allowed with a verbal recommendation from the pediatrician'], correct: 2, explanation: '§749.1405(e) states that an infant who can roll over without assistance must not be swaddled. Other safe sleep rules in §749.1405 require a face-up sleep position unless a health-care professional orders otherwise, nothing covering the infant\'s head, face, or crib, no co-sleeping with anyone in any location, and no sleeping in a restrictive device such as a car seat, swing, or bouncy seat.' },
      { id: 'p4q19', domain: 'Daily Care & Discipline (Subch. M)', question: 'Unless a health-care professional recommends otherwise, caregivers must hold an infant during feeding if the infant is birth through how many months old, or cannot sit unassisted in a highchair?', options: ['Three months', 'Six months', 'Nine months', 'Twelve months'], correct: 1, explanation: '§749.1409(b) requires caregivers to hold an infant while feeding if the infant is birth through six months old or is unable to sit unassisted in a highchair or other seating equipment, unless the health-care professional recommends otherwise. A bottle must never be propped by anything other than the infant\'s or caregiver\'s hands (§749.1409(c)).' },
      { id: 'p4q20', domain: 'Daily Care & Discipline (Subch. M)', question: 'Which item may a foster home NOT use for infants under §749.1407(b)?', options: ['A highchair with the safety straps fastened', 'A stroller used according to the manufacturer\'s instructions', 'A full-sized crib with a firm, flat mattress', 'A baby walker'], correct: 3, explanation: '§749.1407(b) prohibits baby walkers, baby bungee jumpers, and accordion safety gates for infants. Highchairs, swings, strollers, infant carriers, rockers, and bouncer seats may be used only with the safety straps fastened and the manufacturer\'s instructions followed (§749.1407(a)).' },
      { id: 'p4q21', domain: 'Daily Care & Discipline (Subch. M)', question: 'Which duty does §749.1421 assign to the CPA regarding the education of each child in care?', options: ['Designating a liaison between the CPA and the child\'s school', 'Selecting the school district that the child is required to attend', 'Appointing a court-approved educational surrogate for every child in care', 'Enrolling each child only in a privately accredited school program'], correct: 0, explanation: '§749.1421 requires the CPA to arrange appropriate education, including ensuring the child attends an accredited or otherwise state-recognized program in the least restrictive setting, advocating for entitled services such as an IEP, ensuring the program fits the child\'s intellectual and social functioning, and designating a CPA-school liaison. Caregivers have separate duties to request and attend ARD, IEP, and ITP meetings (§749.1423).' },
      { id: 'p4q22', domain: 'Daily Care & Discipline (Subch. M)', question: 'Which standard must a foster parent use to decide whether a child in care may take part in a childhood activity, including an unsupervised one?', options: ['The least restrictive environment standard', 'The ordinary care standard used by licensed child care centers', 'The best interest of the family standard', 'The reasonable and prudent parent standard'], correct: 3, explanation: '§749.1419 requires a foster parent to ensure a child in care can participate in childhood activities, including unsupervised activities, using the reasonable and prudent parent standard. The foster parent considers the child\'s age, maturity, abilities, developmental level, and desires, plus behavioral history and ability to safely participate given the circumstances, hazards, risks, and supervision.' },
      { id: 'p4q23', domain: 'Medical & Dental (Subch. N)', question: 'At admission, the CPA must verify that a child in care has had a medical exam and a dental exam within the past year. The dental exam check applies if the child is at least how old?', options: ['Six months old', '12 months old', 'Two years old', 'Three years old'], correct: 0, explanation: '§749.1501(b) requires the CPA at admission to verify a medical examination within the past year, and a dental examination within the past year if the child is at least six months old. If either exam has not occurred in that time frame, the CPA must schedule any medical or dental examinations the child may need.' },
      { id: 'p4q24', domain: 'Medical & Dental (Subch. N)', question: 'Before a child in care may self-administer medication, what must the CPA do under §749.1501(f)?', options: ['Obtain a court order for the child, then notify Child Care Regulation of the arrangement', 'Obtain verbal consent from the parent and send a written notice to the school nurse', 'Obtain written parental consent, update the service plan, and consult the prescriber', 'Have the foster parent sign a liability waiver and keep the medication locked in the home'], correct: 2, explanation: '§749.1501(f) allows a child to self-administer medication only after the CPA (1) obtains written parental consent, (2) updates the service plan to include self-administration and any caregiver supervision requirements, and (3) consults the prescribing health-care professional and notes that professional\'s concerns in the child\'s record. When a child self-administers, the home must review the medication and record the daily dosage (§749.1505(e)).' },
      { id: 'p4q25', domain: 'Medical & Dental (Subch. N)', question: 'A foster parent gives a 4-year-old child in care a non-prescription vitamin supplement. What does §749.1505(b) require?', options: ['Make no entry, since only prescription medications must be recorded in the log', 'Make a daily medication log entry, since supplements given to a child under five are logged', 'Make an entry only if the supplement is given more than once in a single day', 'Make an entry only if the child has a documented allergy to a listed ingredient'], correct: 1, explanation: '§749.1505(b)(1) requires a daily medication log for each prescription medication given to a child of any age and for any non-prescription medication or supplement given to a child under five. The log must show the child\'s name, who gave the medication, its name, strength, and dosage, and the date and time (§749.1505(c)). Medication errors, adverse reactions, and side effects must also be documented (§749.1505(b)(2)).' },
      { id: 'p4q26', domain: 'Emergency Behavior Intervention (Subch. O)', question: 'Which emergency behavior intervention may a caregiver use under §749.1601(c)?', options: ['Seclusion in a locked room', 'A mechanical restraint', 'A short personal restraint', 'A chemical restraint'], correct: 2, explanation: '§749.1601(c) limits caregivers to personal restraints, short personal restraints, and emergency medication; chemical restraints, mechanical restraints, and seclusion are not allowed. A short personal restraint lasts no longer than one minute and any caregiver may administer it, while personal restraints and emergency medication require a caregiver allowed by CPA policy and trained in the CPA EBI curriculum (§749.1601(d), (f), (g)).' },
      { id: 'p4q27', domain: 'Emergency Behavior Intervention (Subch. O)', question: 'What is the longest a child in care may be held in a personal restraint (not a short personal restraint)?', options: ['10 minutes', '15 minutes', '30 minutes', '60 minutes'], correct: 2, explanation: '§749.1605(b) requires a child to be released from a personal restraint immediately if an emergency health situation occurs, emergency medication is given, or the emergency ends, and in any case no later than 30 minutes after the restraint was administered. A short personal restraint ends when the danger is gone or the one-minute limit is reached (§749.1605(c)).' },
      { id: 'p4q28', domain: 'Emergency Behavior Intervention (Subch. O)', question: 'After a personal restraint or emergency medication is given to a child in care, the CPA must give written notice to the child\'s parent no later than:', options: ['24 hours after the intervention', '72 hours after the intervention', '48 hours after the intervention', '7 days after the intervention'], correct: 1, explanation: '§749.1625(a) requires written notice to the parent no later than 72 hours after a personal restraint or emergency medication. The notice, kept in the child\'s record, must describe each restraint or medication (including the medication name and dose and the length of the restraint) and the child\'s condition afterward (§749.1625(b)). Caregivers involved must also talk with child placement staff within 72 hours (§749.1621(b)).' },
      { id: 'p4q29', domain: 'Emergency Behavior Intervention (Subch. O)', question: 'A caregiver has given emergency medication to the same child in care three times in a 30-day period. What does §749.1631 require?', options: ['A triggered review of the placement, service plan, and EBI orders within 30 days', 'An examination of the child by a mental health professional within 30 days', 'A written report to Child Care Regulation within 24 hours of the third dose', 'A review of the use of emergency medication at the next annual home evaluation'], correct: 0, explanation: '§749.1631(a) requires a triggered review no later than 30 days after emergency medication is given to the same child three times in 30 days, or after a personal restraint is used four or more times in seven days, 13 or more times in 30 days, or more often than a written order allows. The service planning team participates and the child is invited. Four triggered reviews within 90 days require an examination by a mental health professional, whose recommendations the CPA must follow (§749.1631(b)-(c)).' },
      { id: 'p4q30', domain: 'Emergency Behavior Intervention (Subch. O)', question: 'Every three months the CPA must review aggregate numbers of EBI by type of intervention and report that information to Child Care Regulation no later than:', options: ['10 days after the end of each quarter', '30 days after the end of each quarter', '60 days after the end of each quarter', '15 days after the end of each quarter'], correct: 3, explanation: '§749.1635(b) requires the CPA every three months to collect, document, and review aggregate EBI numbers by type of intervention and report them to Child Care Regulation no later than 15 days after the end of each quarter. §749.1635(a) also requires a written annual operation evaluation of EBI policies, frequency, patterns, effectiveness, and strategies to reduce the need for EBI.' },
    ],
  },
  {
    id: 'lcpaa-exam-5',
    number: 5,
    title: 'LCPAA Practice Exam 5 — Final Prep',
    description: 'A harder, comprehensive exam on foster-adoptive homes, adoption services, assessment and trafficking victim services, kinship foster homes, and administrator, incident reporting, and record retention duties.',
    questions: [
      { id: 'p5q1', domain: 'Reports & Records (Subch. D)', question: 'How long must a CPA maintain the records of a verified foster home after the home is closed?', options: ['At least two years from the date of closure', 'At least one year after the last child was discharged', 'Permanently, or until transferred to the Bureau of Vital Statistics', 'At least five years, including homes that never received placements'], correct: 3, explanation: '§749.585(c) requires records for verified foster homes to be kept at least five years after the home is closed, including homes that did not receive placements. A foster child\'s record is kept two years from discharge or until any investigation is resolved, whichever is longer (§749.585(b)); adoption records are kept permanently or transferred to the Bureau of Vital Statistics (§749.585(a)); and records of foster or adoptive applicants not verified or approved are kept at least one year after denial (§749.585(e)).' },
      { id: 'p5q2', domain: 'Trafficking Victim Services (Subch. V)', question: 'You are the CPA administrator. A child admitted for trafficking victim services is screened within 72 hours, and the screening shows an immediate need for a medical exam. By when must you obtain the exam under §749.4251?', options: ['Within 24 hours', 'Within 10 days', 'Within 30 days', 'Within five days'], correct: 3, explanation: '§749.4251(3) requires you to obtain the medical examination or tests within five days if the required screening, done within 72 hours of admission, shows an immediate need. The screening looks for the need for a medical exam and for tests for pregnancy, hepatitis B, hepatitis C, HIV, STDs, and tuberculosis. By contrast, behavioral health assessments for PTSD, depression, and anxiety are due within 30 days of admission (§749.4257(a)).' },
      { id: 'p5q3', domain: 'Adoption: Children (Subch. Q)', question: 'You accept a child for adoption placement services. Within how many days after initiating the adoption service plan must you complete it?', options: ['30 days', '45 days', '40 days', '60 days'], correct: 2, explanation: '§749.3321 requires you to initiate the plan when you accept a child or enter a written agreement with the birth parent for adoption placement services, and to complete it within 40 days of initiation. If the child already had a foster care service plan, the adoption service plan may be a continuation of it (§749.3327).' },
      { id: 'p5q4', domain: 'Reports & Records (Subch. D)', question: 'You are the CPA administrator. A 16-year-old in a foster home has just had a third unauthorized absence within 60 days. What do §749.593 and §749.594 require?', options: ['A triggered review within 90 days, with only the child placement staff taking part in the review', 'A triggered review within 30 days, with the child, foster parent, and placement staff taking part', 'Moving up the annual agency evaluation, with no participation by the child or the foster parent', 'Discharge from the foster home and a report to Child Care Regulation within 2 hours of the third absence'], correct: 1, explanation: '§749.593(a) requires a triggered review as soon as possible, but no later than 30 days after the third unauthorized absence within a 60-day timeframe; a regularly scheduled service plan review can serve if it meets the content requirements and occurs within that time. The child, foster parent, and child placement staff must participate, and the parent must be notified at least two weeks beforehand (§749.594). The review must produce a written plan to reduce absences (§749.595).' },
      { id: 'p5q5', domain: 'Reports & Records (Subch. D)', question: 'You are the CPA administrator. A child in care dies at a foster home. When must the CPA notify law enforcement under §749.503(a)(1)?', options: ['Immediately, but no later than 1 hour after the child\'s death', 'As soon as possible, but no later than 2 hours after the death', 'Within 6 hours after the death, through the Abuse and Neglect Hotline', 'Within 24 hours after the death, in writing to the local police department'], correct: 0, explanation: '§749.503(a)(1) requires reports of a child\'s death to Child Care Regulation and to the parents as soon as possible but no later than 2 hours after the death, and to law enforcement immediately but no later than 1 hour after the death. Serious incident reports are made directly to the Texas Abuse and Neglect Hotline, and foster parents must report directly for a child under their care (§749.509).' },
      { id: 'p5q6', domain: 'Adoption: Children (Subch. Q)', question: 'A 14-month-old who does not need treatment services is placed with an adoptive family. What is the minimum number of post-placement face-to-face contacts with the child and adoptive parents required within the first six months under §749.3425?', options: ['Two', 'Three', 'Five', 'Six (monthly)'], correct: 2, explanation: '§749.3425(a)(1) requires a minimum of five face-to-face contacts within the first six months for a child under two who does not need treatment services; two must be with the entire prospective adoptive family and at least one of those two in the adoptive home. A child who needs treatment services or is two or older requires monthly face-to-face contacts during the first six months. After six months, contacts must be at least quarterly in the home with the entire family until the decree is entered (§749.3425(c)).' },
      { id: 'p5q7', domain: 'Trafficking Victim Services (Subch. V)', question: 'Under §749.4155 and §749.4157, how many hours of annual training specific to trafficking victims must each caregiver complete, and what must one of those hours cover?', options: ['Two hours, including one hour on the legal rights of trafficking victims in court', 'Four hours, including one hour on law enforcement reporting procedures for runaways', 'Four hours, including one hour on compassion fatigue and secondary traumatic stress', 'Eight hours, including two hours on preventing compassion fatigue in caregivers'], correct: 2, explanation: '§749.4155 requires four hours of trafficking-specific annual training for each caregiver, and §749.4157 says those four hours must include one hour on preventing compassion fatigue and secondary traumatic stress and three hours on topics suited to the needs of the children in care. In a home with two foster parents the total is 50 hours (8 EBI, 2 trauma-informed care, 4 trafficking each); other caregivers need 30 hours with the same minimums.' },
      { id: 'p5q8', domain: 'Foster-Adoptive Homes (Subch. P)', question: 'You are the CPA administrator. A foster child whose parents\' rights have not been terminated lives with foster parents who say they want to adopt. The couple is verified as a foster home but has not been approved as an adoptive home. Is this a "legal risk placement" under §749.3221?', options: ['No; a legal risk placement requires a home both verified as foster and approved as adoptive', 'Yes; any foster placement of a child whose parents\' rights are not terminated is a legal risk placement', 'Yes, as long as the foster parents sign a written statement of their intent to adopt the child', 'No; a legal risk placement exists only after parental rights have been terminated for the child'], correct: 0, explanation: '§749.3221(a) defines a legal risk placement as one where the child is not available for adoption because parental rights have not been terminated, the child is placed in a home jointly verified as a foster home and approved as an adoptive home, and you intend the placement to change to adoption once the child is eligible. Under §749.3221(b), merely placing a child with foster parents who want to adopt but are not approved as an adoptive home is not a legal risk placement.' },
      { id: 'p5q9', domain: 'Adoption: Children (Subch. Q)', question: 'You are the CPA administrator. A 3-year-old is being placed for adoption, and the required professional assessments were completed four months before the planned placement date. Is that acceptable under §749.3349(e)?', options: ['Yes; assessments for any child under age five may be up to six months old when the child is placed', 'No; assessments for children of this age must be current within 30 days of placement', 'Yes; currency is required only when the child has a diagnosed disability or developmental delay', 'No; for a child 18 months to four years old, assessments must be current within three months'], correct: 3, explanation: '§749.3349(e) requires assessments to be current within 30 days of placement for a child under 18 months, three months for a child 18 months to four years old, and six months for a child five or older. The assessment must always include a medical examination by a licensed physician (§749.3349(b)), and for a child over 18 months an evaluation by a licensed psychiatrist, psychologist, or other licensed or credentialed professional (§749.3349(d)).' },
      { id: 'p5q10', domain: 'Adoption: Children (Subch. Q)', question: 'What is the minimum number of face-to-face contacts required to prepare a child who is 18 months old or older for adoption under §749.3341?', options: ['Three contacts', 'One contact', 'Two contacts', 'Five contacts'], correct: 0, explanation: '§749.3341(b) requires a minimum of three face-to-face contacts with a child who is 18 months old or older to prepare the child for adoption. An infant age zero to 18 months requires a minimum of one face-to-face contact (§749.3341(c)). Overall, contact with a child being considered for adoption must be at least quarterly and meaningful, and each contact must be documented (§749.3341(a), (d)).' },
      { id: 'p5q11', domain: 'Kinship Foster Homes (Subch. W)', question: 'Under §749.4425, when must a second kinship foster parent be certified in pediatric first aid and pediatric CPR?', options: ['Before the CPA issues the verification', 'Within 30 days after the CPA verifies the home', 'Within 90 days after the CPA verifies the home', 'Within 60 days after the CPA verifies the home'], correct: 2, explanation: '§749.4425(a) requires one kinship foster parent to be certified in pediatric first aid and pediatric CPR before the CPA issues the verification; other kinship caregivers, including a second kinship foster parent, must be certified within 90 days after verification. Certificates must show an expiration date and be renewed before it passes (§749.4421(b)). General caregiver and EBI training are due within 60 days after verification (§749.4427).' },
      { id: 'p5q12', domain: 'Trafficking Victim Services (Subch. V)', question: 'A CPA must meet the additional rules of Subchapter V (trafficking victim services) when it provides those services to:', options: ['10 or more children, or at least 25% of the children in its care', '30 or more children, or more than 50% of the children in its care', '25 or more children, or 30% or more of the children in its care', '50 or more children, or all of the children in its care at any given time'], correct: 1, explanation: '§749.4003 requires a CPA to meet the additional rules of Subchapter V if it provides trafficking victim services to 30 or more children or to more than 50% of the children in its care. (The 25 children or 30% figures appear in §749.4153 for general residential operations.)' },
      { id: 'p5q13', domain: 'Adoption: Children (Subch. Q)', question: 'You are the CPA administrator, and a caseworker asks to place a child with prospective adoptive parents before the adoptive home screening is complete. Under §749.3375, when is this permitted?', options: ['Only if the adoptive parent is a second-degree relative or the child\'s immediate prior foster family', 'Only if the family has already adopted another child through your own agency and has a current screening update', 'Whenever CPMS approves the placement in writing and the screening will be finished within 30 days of placement', 'Only if the child is under 18 months old and the birth parent gives written consent to the early placement'], correct: 0, explanation: '§749.3375 allows placement before the adoptive home screening is completed only if the prospective adoptive parent is a member of the child\'s family related by the second degree of consanguinity or affinity, or is the foster family with whom the child lived immediately before the request for an adoptive home screening.' },
      { id: 'p5q14', domain: 'Kinship Foster Homes (Subch. W)', question: 'You are the CPA administrator, and a kinship foster family moves to a new residence. What does §749.4515 allow and require?', options: ['Close the verification and complete a new full screening before any child may stay', 'Issue a temporary verification valid up to six months and inspect the new home within 30 days', 'Issue a temporary verification valid up to 12 months and inspect the new home within 90 days', 'Keep the current verification and inspect the new residence at the next annual evaluation'], correct: 1, explanation: '§749.4515 allows a temporary kinship foster home verification when the home moves from one residence to another; within 30 days of the move the CPA must inspect the new residence for compliance with the health and safety requirements, and the temporary verification is valid for a maximum of six months. Before issuing the non-expiring verification, the CPA must ensure full compliance. Issuing a temporary verification must be reported to Child Care Regulation within two business days (§749.4511(a)(1)).' },
      { id: 'p5q15', domain: 'Assessment Services (Subch. T)', question: 'You admit a 3-year-old into your assessment services program. By when must the assessment report be completed under §749.3893?', options: ['Within 45 days of admission, extendable 15 days with parent approval', 'Within 60 days of admission, with no extension allowed under any circumstance', 'Within 10 days of admission, extendable 30 days with CPMS approval', 'Within 30 days of admission, extendable 15 days with parent approval'], correct: 3, explanation: '§749.3893(b) requires the assessment report within 30 days after admission for a child younger than five and within 45 days for a child five or older. With the parent\'s approval, the time frame may be extended for an additional 15 days, and the need must be documented in the child\'s record (§749.3893(c)). The report must be finished before a planned discharge and a copy given to the parent as soon as it is complete.' },
      { id: 'p5q16', domain: 'Kinship Foster Homes (Subch. W)', question: 'You are the CPA administrator. You verify a kinship foster home in which a kinship foster child is already living. By when must the child\'s admission assessment be complete under §749.4449?', options: ['Within 30 days of verifying the kinship foster home', 'Within 40 days of verifying the kinship foster home', 'Within 40 days of the child\'s original removal from the parents', 'Within 72 hours of verifying the kinship foster home'], correct: 1, explanation: '§749.4449(b) requires the admission assessment within 40 days of verifying the kinship foster home if the child already lives there, and within 40 days of admitting the child if the child is not yet in the home. A DFPS written assessment of the child\'s needs and strengths may be used instead if it is requested and reviewed within that time frame, and the completed assessment must be shared with the kinship foster parents (§749.4449(d)-(e)).' },
      { id: 'p5q17', domain: 'Adoption: Adoptive Parents (Subch. S)', question: 'Unless the court directs otherwise, when must the interview for a post-placement adoptive report be conducted under §749.3749?', options: ['After the child has lived in the adoptive home for at least five months', 'Within 30 days after the child is placed with the adoptive family under the written agreement', 'After the child has lived in the adoptive home for at least 90 days', 'After the child has lived in the adoptive home for at least one year'], correct: 0, explanation: '§749.3749 requires you to conduct the interview for a post-placement adoptive report after the child has resided with the adoptive parent for at least five months, unless otherwise directed by the court, although you may begin gathering written information after placement. The interviews and home visit are not required when a foster family adopts a foster child who has been placed in that home at least six months (§749.3743(b), §749.3747).' },
      { id: 'p5q18', domain: 'Administration (Subch. C & E)', question: 'You are the CPA administrator and will be away from the agency on an extended basis. What does §749.637 require?', options: ['Designate any child placement management staff member, even one without an administrator license', 'Designate an employee, who must be a Licensed CPA Administrator, to oversee the agency', 'Close the agency to new admissions until the administrator returns to full-time duty', 'Give Licensing 30 days notice, with no designee needed if each branch has its own manager'], correct: 1, explanation: '§749.637 requires the administrator to designate an employee to be responsible for the overall administration of the agency while the administrator is absent on a frequent or extended basis, and the designee must be a Licensed Child-Placing Agency Administrator. The administrator must be a full-time employee present at a Texas office (§749.631) with daily supervision and overall responsibility for all offices (§749.635).' },
      { id: 'p5q19', domain: 'Assessment Services (Subch. T)', question: 'You are the administrator of a CPA with an assessment services program. Within how many days after a child\'s admission must the child\'s individual plan for the assessment be completed?', options: ['5 days', '10 days', '14 days', '30 days'], correct: 1, explanation: '§749.3861 requires you to complete the child\'s individual plan for the assessment within 10 days from the date of admission and to document it in the child\'s record. The plan must include time frames, care recommendations, any treatment, and current caregiver data (§749.3865(a)), and the common application must not serve as the plan (§749.3865(b)). The parent must review the plan and receive a copy (§749.3871(b)).' },
      { id: 'p5q20', domain: 'Kinship Foster Homes (Subch. W)', question: 'A kinship foster home wants to care for seven children, counting its own biological children and a child receiving respite services. What must the CPA do under §749.4517?', options: ['Document CPMS approval of the increase in the service plan of each kinship foster child', 'Obtain written consent for the increase from the parent of each child currently living in the home', 'Nothing, since capacity depends on the number of caregivers and two may care for eight', 'Complete Form 4003 (Foster Family Home Capacity Exception) and request a variance from CCR'], correct: 3, explanation: '§749.4517(a) limits a kinship foster home to six children regardless of the number of caregivers or the children\'s ages, counting kinship foster children, adopted and biological children, respite children, and daycare children. Under §749.4517(b), seven or eight children may be cared for only as recommended and approved by DFPS and a CPA, and the CPA must complete Form 4003 and request a variance from Child Care Regulation.' },
      { id: 'p5q21', domain: 'Administration (Subch. C & E)', question: 'Which change to your CPA requires written notice to your Licensing Representative at least 30 days beforehand under §749.153?', options: ['A new individual becoming a controlling person', 'Changes to the plans required under §749.101(3) and (4)', 'Moving the agency to another location', 'A vacancy in the administrator position'], correct: 2, explanation: '§749.153(a)(1) requires notice as soon as possible but at least 30 days before you change the legal structure of the agency or governing body, move the agency, open a branch office, or change hours of operation. Changes to the required plans and policies need notice at least 15 days before (§749.153(a)(2)), while a change in administrator or controlling person is reported no later than two days after it occurs (§749.153(a)(3)).' },
      { id: 'p5q22', domain: 'Administration (Subch. C & E)', question: 'What liability insurance must a CPA carry under §749.155, and what must it provide to Licensing each year?', options: ['$100,000 per occurrence for injury to a child, with proof of coverage at each annual permit renewal', '$500,000 per occurrence for injury to a child, with proof of coverage each year by January 31', '$300,000 total for the year for injury to a child, with proof of coverage only when Licensing asks', '$300,000 per occurrence for injury to a child, with proof of coverage by the permit anniversary date'], correct: 3, explanation: '§749.155 requires $300,000 of liability coverage for each occurrence of negligence that covers injury to a child on the agency premises or in its care, and proof of coverage to Licensing each year by the anniversary date of permit issuance. If a CPA cannot carry the insurance for an acceptable reason (§749.157), it must notify Licensing in writing and notify the parent of each child in writing before admission, or within 14 days after it stops carrying coverage (§749.159).' },
      { id: 'p5q23', domain: 'Reports & Records (Subch. D)', question: 'You are the CPA administrator. Licensing cites one of your foster homes for a safe sleeping deficiency. What must you do under §749.519?', options: ['Within five days of notice, notify parents of children in every foster home you verify, on Form 2970', 'Within 24 hours, notify only the parents of children who are currently placed in the cited home', 'Within 30 days, notify the parents of children who were placed in the cited home in the past year', 'Notify parents only after an investigation has confirmed that the deficiency actually occurred'], correct: 0, explanation: '§749.519(a)-(c) requires notice within five days after you receive notification of the deficiency to the parents of each child in care of each foster home your CPA has verified at that time, and a safe sleeping deficiency uses Form 2970 (abuse, neglect, or exploitation deficiencies use Form 7266). You must keep proof of the written notices available for Licensing (§749.519(e)). "Parent" includes the person with legal responsibility, such as a DFPS caseworker.' },
      { id: 'p5q24', domain: 'Adoption: Adoptive Parents (Subch. S)', question: 'You are the CPA administrator. An approved adoptive family has been waiting for a placement and their home screening was approved 14 months ago with no changes in the household. What does §749.3633 require?', options: ['An update every 12 months, including a home visit with everyone present in the prior 90 days', 'No update is needed, because an update is required only after a major life change in the family', 'An update every 24 months, including an individual interview with each applicant and child', 'An update every 12 months, with a home visit made with all members present at any time in the prior year'], correct: 0, explanation: '§749.3633(a) requires an update to an adoptive home screening every 12 months and after a major life change in the family. The update must review and update each required category of information and document at least one visit to the home, with all household members present, within the 90-day period before CPMS approves the update (§749.3633(b)). No update is required for adoptive homes that are also foster homes verified by your agency (§749.3633(c)).' },
      { id: 'p5q25', domain: 'Administration (Subch. C & E)', question: 'Your CPA has no back-up administrator and the administrator position becomes vacant. How long do you have to obtain a licensed child-care administrator before Licensing can cite you for not having one?', options: ['14 days after the vacancy begins', '60 days after the vacancy begins', '30 days after the vacancy begins', '90 days after the vacancy begins'], correct: 1, explanation: '§749.154 gives a CPA with no back-up administrator 60 days from the date the position becomes vacant to obtain a licensed child-care administrator before it can be cited. The vacancy must still be reported to the Licensing Representative no later than two days afterward (§749.153(a)(3)(A)).' },
      { id: 'p5q26', domain: 'Foster-Adoptive Homes (Subch. P)', question: 'You are verifying applicants as both a foster family home and an adoptive home. How may you handle the screening report under §749.3203?', options: ['Complete only the foster home screening, since it replaces the adoptive home screening', 'Complete only the adoptive screening and add a short addendum for foster care', 'Combine them into one report, if the requirements for each screening are covered', 'Use two separate reports, because the two screenings may never be combined'], correct: 2, explanation: '§749.3203(a) requires you to follow all rules for verifying a foster family home and for approving an adoptive home. §749.3203(b) allows you to combine the two screenings into one screening report as long as the requirements for each screening are covered.' },
      { id: 'p5q27', domain: 'Reports & Records (Subch. D)', question: 'You are the CPA administrator. A 15-year-old foster child who was previously alleged to be a trafficking victim is discovered missing and is still missing. When must the CPA report the absence under §749.503(a)(10)?', options: ['No later than 6 hours after the absence was discovered', 'Immediately, because the usual 6-hour window does not apply', 'Within 2 hours after determining the child is not on the premises', 'Within 24 hours after the CPA becomes aware of the absence'], correct: 1, explanation: '§749.503(a)(10) allows a report no later than 6 hours after discovery when a child 13 or older is still missing, but the CPA must report immediately if the child was previously alleged or determined to be a trafficking victim, or if the CPA believes the child was abducted or does not intend to return. Shorter timelines apply to children under 6 (§749.503(a)(8)) and 6 to 12 (§749.503(a)(9)), where the 2-hour clock runs from notifying law enforcement or from determining the child is not on the premises. If the child returns before the deadline, the CPA documents it within 24 hours instead (§749.503(c)).' },
      { id: 'p5q28', domain: 'Kinship Foster Homes (Subch. W)', question: 'What post-placement contact must child placement staff have with a kinship foster child under §749.4451?', options: ['Monthly face-to-face contact, with at least half of the contacts in the foster home', 'Quarterly face-to-face contact, with all of the contacts held in the foster home or by video', 'Monthly face-to-face contact, with an in-home visit at least every six months', 'Contact every two months, with about half of the contacts made by telephone'], correct: 0, explanation: '§749.4451(a)-(b) requires monthly face-to-face contact with a kinship foster child, and at least half of the contacts must occur in the foster home. The visits must ensure the child is safe and basic needs are met, last long enough to address the needs of a verbal child (or observe a non-verbal child), allow a private meeting, and give the child a chance to say how the placement is going.' },
      { id: 'p5q29', domain: 'Reports & Records (Subch. D)', question: 'How long must a CPA keep its copies of serious incident reports, and how must they be kept?', options: ['One year, available to Licensing within 48 hours of a written request', 'Five years, kept only in the child\'s record', 'Two years, easily accessible to Licensing upon request', 'Until the child is discharged, and then destroyed'], correct: 2, explanation: '§749.515 requires a CPA to keep a copy of incident reports on file for two years, easily accessible to Licensing upon request. Other retention periods differ: annual summary logs of unauthorized absences and the six-month agency evaluations of unauthorized absences must be kept five years (§749.591(b), §749.596(d)).' },
      { id: 'p5q30', domain: 'Adoption: Birth Parents (Subch. R)', question: 'Before birth parents relinquish their parental rights, what face-to-face contact must child placement staff have with them under §749.3503(a)(1)?', options: ['At least one contact, which must take place after the birth of the child', 'At least three contacts, all of which must take place before the child is born', 'At least two contacts, both of which are held on the same day that the rights are relinquished', 'At least two contacts over two or more days, with one interview after the child is born'], correct: 3, explanation: '§749.3503(a)(1) requires two face-to-face contacts with birth parents before relinquishment, over a period of two or more days, with at least one interview after the birth of the child. If face-to-face contact with the birth father is not feasible, you must document the justification. The contacts must help birth parents make a free choice without being pressured (§749.3503(c)).' },
    ],
  },
];
